import socket,sys,time,json
import arena
class Engine:
 def __init__(self):
  self.s=socket.socket(socket.AF_UNIX); self.s.connect('/run/match/opponent-stockfish.sock'); self.f=self.s.makefile('r'); self.send('uci'); self.until('uciok'); self.send('setoption name Hash value 256'); self.send('setoption name Threads value 2'); self.send('isready'); self.until('readyok')
 def send(self,x): self.s.sendall((x+'\n').encode())
 def until(self,prefix):
  lines=[]
  while True:
   line=self.f.readline().strip(); lines.append(line)
   if line.startswith(prefix): return lines
 def analyze(self,b,secs=60,searchmoves=None):
  self.send('position startpos moves '+' '.join(m.uci() for m in b.move_stack))
  cmd='go movetime '+str(int(secs*1000))
  if searchmoves: cmd+=' searchmoves '+' '.join(searchmoves)
  self.send(cmd)
  lines=self.until('bestmove')
  return lines
 def close(self): self.send('quit'); self.s.close()
if __name__=='__main__':
 b=arena.load_board(); e=Engine(); lines=e.analyze(b,float(sys.argv[1]) if len(sys.argv)>1 else 60,sys.argv[2:] or None); print('\n'.join(lines[-12:])); e.close()
 open('analysis.log','a').write(b.fen()+'\n'+'\n'.join(lines)+'\n')
